# ! [doc = " SOLID, just like macOS, has an API to register TLS destructors. But since"] # ! [doc = " it does not allow specifying an argument to that function, and will not run"] # ! [doc = " destructors for terminated tasks, we still keep our own list."] use split_decls_genesis :: ourprelude :: * ; use crate :: cell :: Cell ; use crate :: sys :: pal :: abi ; use crate :: sys :: pal :: itron :: task ; use crate :: sys :: thread_local :: destructors ; pub fn enable () { #[thread_local] static REGISTERED : Cell < bool > = Cell :: new (false) ; if ! REGISTERED . replace (true) { let tid = task :: current_task_id_aborting () ; unsafe { abi :: SOLID_TLS_AddDestructor (tid as i32 , tls_dtor) } ; } unsafe extern "C" fn tls_dtor (_unused : * mut u8) { unsafe { destructors :: run () ; crate :: rt :: thread_cleanup () ; } } }